import{_ as e,o,c as r,a2 as s}from"./chunks/framework.BjkiRu3Q.js";const t="/images/cliente/producto-detalle.webp",g=JSON.parse('{"title":"4. Ficha de Producto, Fotografías HD y Variantes","description":"","frontmatter":{},"headers":[],"relativePath":"cliente/producto.md","filePath":"cliente/producto.md"}'),l={name:"cliente/producto.md"};function n(i,a,c,d,u,p){return o(),r("div",null,[...a[0]||(a[0]=[s('<h1 id="_4-ficha-de-producto-fotografias-hd-y-variantes" tabindex="-1">4. Ficha de Producto, Fotografías HD y Variantes <a class="header-anchor" href="#_4-ficha-de-producto-fotografias-hd-y-variantes" aria-label="Permalink to &quot;4. Ficha de Producto, Fotografías HD y Variantes&quot;">​</a></h1><p>Al abrir cualquier producto de la tienda encontrarás sus fotografías en alta resolución, las opciones de color, capacidad o talla, las especificaciones técnicas del fabricante y las opciones de compra directa.</p><hr><h2 id="_4-1-que-encontraras-en-la-pagina-del-producto" tabindex="-1">4.1 Qué encontrarás en la página del producto <a class="header-anchor" href="#_4-1-que-encontraras-en-la-pagina-del-producto" aria-label="Permalink to &quot;4.1 Qué encontrarás en la página del producto&quot;">​</a></h2><div class="screenshot-box"><div class="screenshot-header"><div class="screenshot-dots"><span class="screenshot-dot red"></span><span class="screenshot-dot yellow"></span><span class="screenshot-dot green"></span></div><span class="screenshot-title">Ficha del Producto, Fotos y Variantes</span><span class="screenshot-url">https://pyme.rsfsecure.site/producto/...</span></div><div class="screenshot-body"><img src="'+t+'" alt="Ficha del Producto, Fotos y Variantes" loading="lazy" decoding="async"></div></div><hr><h2 id="_4-2-como-usar-la-galeria-de-fotos-y-el-visor-hd" tabindex="-1">4.2 Cómo Usar la Galería de Fotos y el Visor HD <a class="header-anchor" href="#_4-2-como-usar-la-galeria-de-fotos-y-el-visor-hd" aria-label="Permalink to &quot;4.2 Cómo Usar la Galería de Fotos y el Visor HD&quot;">​</a></h2><ul><li><strong>Navegar entre fotografías:</strong> Haz clic sobre cualquiera de las miniaturas ubicadas debajo de la foto principal o utiliza las flechas laterales <code>&lt;</code> y <code>&gt;</code>. Gracias al sistema de precarga inteligente, las imágenes cambian al instante sin parpadeos ni demoras.</li><li><strong>Ampliación con lupa (Zoom):</strong> Si estás en computadora, pasa el cursor sobre la foto principal para ver texturas, acabados y puertos en aumento.</li><li><strong>Visor a Pantalla Completa:</strong> Haz clic en el botón de pantalla completa en la esquina superior de la foto para examinarla en su máxima resolución.</li><li><strong>Respaldo de Marca Oficial:</strong> Junto al título del producto verás el logotipo de la marca fabricante (por ejemplo <em>GoPro</em>, <em>MSI</em>, <em>Apple</em>, <em>Samsung</em>) para garantizar que se trata de mercancía 100% original.</li></ul><hr><h2 id="_4-3-como-elegir-color-talla-o-capacidad-variantes" tabindex="-1">4.3 Cómo Elegir Color, Talla o Capacidad (Variantes) <a class="header-anchor" href="#_4-3-como-elegir-color-talla-o-capacidad-variantes" aria-label="Permalink to &quot;4.3 Cómo Elegir Color, Talla o Capacidad (Variantes)&quot;">​</a></h2><p>Muchos productos ofrecen diferentes opciones de almacenamiento, color o medida (por ejemplo: un disco duro de 1TB o 2TB, o una cámara con kit de accesorios):</p><ol><li>Observa los recuadros de <strong>Variantes Disponibles</strong> situados arriba del botón de compra.</li><li>Haz clic sobre la opción de tu preferencia.</li><li>El precio final, las fotografías de la galería y la disponibilidad de inventario se sincronizarán al segundo.</li><li>Si una variante aparece marcada como <strong>&quot;Agotado&quot;</strong>, el botón de compra se desactivará de forma preventiva para asegurarte de que nunca pagues por un artículo sin existencias físicas en bodega.</li></ol><hr><h2 id="_4-4-diferencia-entre-agregar-al-carrito-y-comprar-ahora" tabindex="-1">4.4 Diferencia entre &quot;Agregar al Carrito&quot; y &quot;Comprar Ahora&quot; <a class="header-anchor" href="#_4-4-diferencia-entre-agregar-al-carrito-y-comprar-ahora" aria-label="Permalink to &quot;4.4 Diferencia entre &quot;Agregar al Carrito&quot; y &quot;Comprar Ahora&quot;&quot;">​</a></h2><p>Encontrarás dos botones principales de compra:</p><ul><li><strong>Botón &quot;Agregar al Carrito&quot;:</strong> Recomendado si deseas seguir mirando otros artículos en la tienda antes de pasar a pagar. Tu artículo quedará guardado en tu bolsa lateral sin comprometer tu navegación.</li><li><strong>Botón &quot;Comprar Ahora&quot;:</strong> Si solo vas a comprar ese producto en particular, este botón te lleva de forma directa al paso de checkout, ahorrándote clics.</li><li><strong>Botón &quot;Guardar en Favoritos&quot;:</strong> Si te gusta el producto pero planeas comprarlo en quincena o consultarlo luego, pulsa el botón de favoritos para guardarlo en tu lista personal.</li></ul><hr><h2 id="_4-5-preguntas-frecuentes-sobre-productos" tabindex="-1">4.5 Preguntas Frecuentes sobre Productos <a class="header-anchor" href="#_4-5-preguntas-frecuentes-sobre-productos" aria-label="Permalink to &quot;4.5 Preguntas Frecuentes sobre Productos&quot;">​</a></h2><details class="details custom-block"><summary>¿Los precios mostrados incluyen el impuesto del 7% ITBMS?</summary><p>El precio principal refleja el costo del producto y en el desglose inferior o al agregarlo al carrito verás calculado el <strong>7% de ITBMS</strong> reglamentario de la República de Panamá, sin cobros ocultos ni sorpresas en el total.</p></details><details class="details custom-block"><summary>¿Los productos cuentan con garantía local en Panamá?</summary><p>Sí. Todos los artículos vendidos en PayMe Panamá son nuevos y cuentan con garantía legal respaldada por factura fiscal. Dependiendo de la categoría y fabricante, dispones de entre 30 días y 1 año de garantía oficial.</p></details>',20)])])}const h=e(l,[["render",n]]);export{g as __pageData,h as default};
